chargePrecisionShield() {
  const charge = this.scoreMgr.perfects % 3;
  this.audio.playPerfect(charge);
  const feedback = document.getElementById("precision-charge");
  feedback.textContent = charge ? `ESCUDO · ${charge}/3 CAMBIOS PERFECTOS` : "ESCUDO ACTIVO · 3 S";
  feedback.parentElement.classList.toggle("shield-ready", charge === 0);
  if (charge === 0) {
    this.player.shieldTimer = Math.max(this.player.shieldTimer, 3);
    this.player.emitBurst(24, 0x60f5cf);
  }
}
